-- Private account exposure ledger. Only authenticated Edge code chooses the actor.
create schema br_content;
revoke all on schema br_content from public,anon,authenticated;
grant usage on schema br_content to service_role;
create table br_content.catalogue(
 game text not null,id text not null check(length(id) between 1 and 200),
 topic text not null default '',eligible boolean not null default true,
 published_at timestamptz not null default now(),primary key(game,id)
);
create table br_content.exposures(
 user_id uuid not null references auth.users(id) on delete cascade,
 game text not null,id text not null,first_shown timestamptz not null default now(),
 imported boolean not null default false,last_shown timestamptz not null default now(),
 primary key(user_id,game,id),foreign key(game,id) references br_content.catalogue(game,id)
);
create table br_content.selections(
 user_id uuid not null references auth.users(id) on delete cascade,
 game text not null,week date not null,ids text[] not null default '{}',
 check(cardinality(ids)<=100),primary key(user_id,game,week)
);
create table br_content.programme(
 singleton boolean primary key default true check(singleton),
 invoice_id text not null,subscription_id text not null,paid_at timestamptz not null,
 activated_at timestamptz not null default now(),state text not null default 'inventory_review' check(state='inventory_review')
);
alter table br_content.catalogue enable row level security;
alter table br_content.exposures enable row level security;
alter table br_content.selections enable row level security;
alter table br_content.programme enable row level security;
grant select,insert,update,delete on all tables in schema br_content to service_role;

create function public.content_library_server(p_action text,p_data jsonb)
returns jsonb language plpgsql security invoker set search_path='' as $$
declare
 uid uuid; g text; monday date:=date_trunc('week',now() at time zone 'Australia/Sydney')::date;
 chosen text[]; fresh text[]; replay boolean:=false; challenge text; imported_ids jsonb; receipt jsonb;
begin
 if p_action='activate' then
  if p_data->>'environment' is distinct from 'live' or p_data->>'item' is distinct from 'monthly' or coalesce((p_data->>'amount_paid')::int,0)<499
   or coalesce(p_data->>'invoice_id','') !~ '^in_' or coalesce(p_data->>'subscription_id','') !~ '^sub_'
   or coalesce(p_data->>'payment_intent','') !~ '^pi_' or p_data->>'paid_at' is null then raise exception 'Verified live monthly payment required';end if;
  insert into br_content.programme(invoice_id,subscription_id,paid_at)
   values(p_data->>'invoice_id',p_data->>'subscription_id',(p_data->>'paid_at')::timestamptz) on conflict do nothing;
  return jsonb_build_object('active',true);
 end if;
 if p_action not in ('sync','shown') then raise exception 'Unknown library action';end if;
 uid:=(p_data->>'user_id')::uuid;g:=p_data->>'game';
 if uid is null or not exists(select 1 from br_content.catalogue where game=g) then raise exception 'Invalid account/game';end if;
 -- Serialize imports, weekly allocation and actual exposures for the account/game.
 perform pg_advisory_xact_lock(hashtextextended(uid::text||':'||g,0));
 imported_ids:=coalesce(p_data->'seen','[]');
 if jsonb_typeof(imported_ids)<>'array' or jsonb_array_length(imported_ids)>20000 then raise exception 'Invalid history';end if;
 insert into br_content.exposures(user_id,game,id,imported)
 select uid,g,c.id,true from br_content.catalogue c join (select distinct jsonb_array_elements_text(imported_ids) id) i on i.id=c.id where c.game=g
 on conflict do nothing;
 if p_action='shown' then
  challenge:=p_data->>'id';
  if not exists(select 1 from br_content.catalogue where game=g and id=challenge) then raise exception 'Unknown challenge';end if;
  replay:=exists(select 1 from br_content.exposures where user_id=uid and game=g and id=challenge);
  insert into br_content.exposures(user_id,game,id) values(uid,g,challenge)
  on conflict(user_id,game,id) do update set last_shown=now();
 end if;
 select ids into chosen from br_content.selections where user_id=uid and game=g and week=monday;
 -- Daily-only sync must not silently assign an unopened Unlimited selection.
 if coalesce((p_data->>'allocate')::boolean,false) then
  insert into br_content.selections(user_id,game,week) values(uid,g,monday) on conflict do nothing;
  select ids into chosen from br_content.selections where user_id=uid and game=g and week=monday for update;
  with ranked as (
   select c.id,c.topic,row_number() over(partition by c.topic order by md5(monday::text||g||c.id),c.id) n
   from br_content.catalogue c where c.game=g and c.eligible and not(c.id=any(chosen))
   and not exists(select 1 from br_content.exposures e where e.user_id=uid and e.game=g and e.id=c.id)
  ) select coalesce(array_agg(id order by n,topic,id),'{}') into fresh from (select * from ranked order by n,topic,id limit greatest(0,100-cardinality(chosen))) r;
  chosen:=chosen||fresh;
  update br_content.selections set ids=chosen where user_id=uid and game=g and week=monday;
 end if;
 return jsonb_build_object('week',monday,'ids',coalesce(chosen,'{}'), 'replay',replay,
  'seen',coalesce((select jsonb_agg(id order by id) from br_content.exposures where user_id=uid and game=g),'[]'::jsonb));
end $$;
revoke all on function public.content_library_server(text,jsonb) from public,anon,authenticated;
grant execute on function public.content_library_server(text,jsonb) to service_role;

