insert into br_content.catalogue(game,id,topic) select 'codebreak',lpad(i::text,4,'0'),left(lpad(i::text,4,'0'),1) from generate_series(0,9999) i;

-- Private demand report. No authoring job and no fixed monthly production quota.
create view br_content.inventory_review with(security_invoker=true) as
with active as (
 select distinct s.user_id from br_billing.live_sessions s where s.item='monthly' and s.state='active' and s.paid_through>now()
 and exists(select 1 from br_content.exposures e where e.user_id=s.user_id and e.last_shown>now()-interval '28 days')
),games as(select game,count(*)::int total from br_content.catalogue where eligible group by game),
counts as(
 select a.user_id,g.game,g.total,
 (select count(*)::int from br_content.exposures e join br_content.catalogue c using(game,id) where e.user_id=a.user_id and e.game=g.game and c.eligible) seen,
 (select count(*)::int from br_content.exposures e join br_content.catalogue c using(game,id) where e.user_id=a.user_id and e.game=g.game and c.eligible and not e.imported and e.first_shown>now()-interval '28 days') consumed_28_days
 from active a cross join games g where exists(select 1 from br_content.programme)
)
select *,total-seen unseen,case when consumed_28_days>0 then round((total-seen)*4.0/consumed_28_days,2) end weeks_at_recent_rate,
 case when consumed_28_days=0 then 'observe_usage' when (total-seen)*4.0/consumed_28_days<=4 then 'plan_top_up' else 'sufficient_reserve' end recommendation
from counts;
grant select on br_content.inventory_review to service_role;
